package dev.bennett.codexmeter;
import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.Bundle;import android.text.*;import android.widget.*;
import androidx.appcompat.app.*;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.core.content.FileProvider;
import org.json.*;import java.util.*;
public final class BetaProfileActivity extends AppCompatActivity {
    AlertDialog selection;String account,pendingAccount;JSONObject state;ImageView preview;byte[] png,pending;long generation;Bitmap image;boolean dark;Button save,share;TextView status;
    final ActivityResultLauncher<String> create=registerForActivityResult(new ActivityResultContracts.CreateDocument("image/png"),this::write);
    @Override protected void onCreate(Bundle bundle){Ui.applySelectedTheme(this);super.onCreate(bundle);dark=Ui.isDark(this);LinearLayout body=Ui.installPage(this,BetaCopy.t(this,"share"),true).content;body.addView(BetaUi.note(this,BetaCopy.t(this,"profile_note"),dark));body.addView(BetaUi.row(this,BetaCopy.t(this,"name"),BetaIdentity.name(this),dark,()->BetaIdentity.edit(this,this::reload)));
        preview=new ImageView(this);preview.setAdjustViewBounds(true);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);preview.setContentDescription(BetaCopy.t(this,"preview"));body.addView(preview,new LinearLayout.LayoutParams(-1,-2));status=BetaUi.note(this,"",dark);body.addView(status);
        body.addView(BetaUi.row(this,BetaExperienceUi.t(this,"프로필 프레임","Profile frame"),"",dark,this::chooseFrame));
        body.addView(BetaUi.row(this,BetaCopy.ko(this)?"대표 메달 변경":"Choose featured medals","",dark,this::choose));save=BetaUi.action(this,BetaCopy.t(this,"export_profile"),false,dark,()->{if(png!=null&&BetaUi.current(this,account)){pending=png.clone();pendingAccount=account;create.launch("GPT-HUD-profile.png");}});body.addView(save);share=BetaUi.action(this,BetaCopy.t(this,"share"),true,dark,this::share);body.addView(share);save.setEnabled(false);share.setEnabled(false);androidx.swiperefreshlayout.widget.SwipeRefreshLayout refresh=findViewById(R.id.dashboard_refresh);refresh.setEnabled(false);
    }
    @Override protected void onResume(){super.onResume();reload();}
    @Override protected void onDestroy(){generation++;if(selection!=null)selection.dismiss();pending=null;png=null;preview.setImageDrawable(null);if(image!=null)image.recycle();super.onDestroy();}
    void reload(){String key=SubscriptionStore.accountKey(this);account=key;long ticket=++generation;png=null;save.setEnabled(false);share.setEnabled(false);if(image!=null){preview.setImageDrawable(null);image.recycle();image=null;}String name=BetaIdentity.name(this);boolean ko=BetaCopy.ko(this);
        BetaGrowthStore.WORKER.execute(()->{JSONObject data=null;Bitmap rendered=null;byte[] bytes=null;try{data=BetaGrowthStore.load(this,key);if(data!=null){rendered=render(data,name,ko,selected(data,key));try(java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){rendered.compress(Bitmap.CompressFormat.PNG,100,out);bytes=out.toByteArray();}}}catch(Exception ignored){}final JSONObject result=data;final Bitmap bitmap=rendered;final byte[] content=bytes;runOnUiThread(()->{if(ticket!=generation||!BetaUi.current(this,key)){if(bitmap!=null)bitmap.recycle();return;}state=result;image=bitmap;png=content;if(bitmap!=null)preview.setImageBitmap(bitmap);status.setText(BetaCopy.t(this,content==null?"pending_growth":"profile_ready"));preview.setContentDescription(BetaMedalUi.equippedTitle(this,BetaIdentity.title(this,result==null?"":result.optString("equipped")))+", Lv. "+(result==null?"":result.optInt("level")));save.setEnabled(content!=null);share.setEnabled(content!=null);});});}
    java.util.List<String> selected(JSONObject s,String key){ArrayList<String> result=new ArrayList<>();JSONObject honors=s.optJSONObject("honors");try{JSONArray chosen=new JSONArray(getSharedPreferences("beta_profile_showcase",0).getString(key,"[]"));for(int i=0;i<chosen.length()&&result.size()<3;i++){String id=chosen.optString(i);if(honors.has(id)&&!result.contains(id))result.add(id);}}catch(Exception ignored){}if(result.isEmpty()&&!getSharedPreferences("beta_profile_showcase",0).contains(key)){ArrayList<String> ids=new ArrayList<>();honors.keys().forEachRemaining(ids::add);ids.sort((a,b)->Long.compare(honors.optLong(b),honors.optLong(a)));result.addAll(ids.subList(0,Math.min(3,ids.size())));}return result;}
    void chooseFrame(){
        if(state==null||!BetaUi.current(this,account))return;ArrayList<String> ids=new ArrayList<>(),names=new ArrayList<>();ids.add("");names.add(BetaExperienceUi.t(this,"기본","Default"));
        for(String id:new String[]{"rpg3.frame_30","rpg3.frame_50"})if(state.optJSONObject("honors").has(id)){ids.add(id);names.add(BetaCatalog.name(id,BetaIdentity.name(this),BetaCopy.ko(this)));}
        String key=account;selection=new AlertDialog.Builder(this).setTitle(BetaExperienceUi.t(this,"획득한 프레임","Owned frames")).setSingleChoiceItems(names.toArray(new String[0]),ids.indexOf(BetaPreferences.prefs(this).getString(key+":frame","")),(d,i)->{if(!BetaUi.current(this,key))return;BetaPreferences.prefs(this).edit().putString(key+":frame",ids.get(i)).apply();d.dismiss();reload();}).setNegativeButton(BetaCopy.t(this,"cancel"),null).show();
    }
    void choose(){if(state==null||!BetaUi.current(this,account))return;JSONObject honors=state.optJSONObject("honors");ArrayList<String> ids=new ArrayList<>();honors.keys().forEachRemaining(ids::add);String[] labels=new String[ids.size()];boolean[] checked=new boolean[ids.size()];List<String> chosen=selected(state,account);for(int i=0;i<ids.size();i++){labels[i]=BetaCatalog.name(ids.get(i),BetaIdentity.name(this),BetaCopy.ko(this));checked[i]=chosen.contains(ids.get(i));}String key=account;
        selection=new AlertDialog.Builder(this).setTitle(BetaCopy.ko(this)?"대표 메달 · 최대 3개":"Featured medals: up to 3").setMultiChoiceItems(labels,checked,(d,i,on)->{if(on){int count=0;for(boolean b:checked)if(b)count++;if(count>3){checked[i]=false;((AlertDialog)d).getListView().setItemChecked(i,false);}}}).setNegativeButton(BetaCopy.t(this,"cancel"),null).setPositiveButton(BetaCopy.t(this,"save"),(d,w)->{if(!BetaUi.current(this,key))return;JSONArray values=new JSONArray();for(int i=0;i<ids.size();i++)if(checked[i])values.put(ids.get(i));getSharedPreferences("beta_profile_showcase",0).edit().putString(key,values.toString()).apply();reload();}).show();}
    Bitmap render(JSONObject s,String name,boolean ko,List<String> medals){int width=840;TextPaint paint=new TextPaint(3);paint.setTypeface(PretendardFont.semibold(this));paint.setColor(0xffedf2fa);String title=BetaCatalog.name(s.optString("equipped"),name,ko);if(s.optString("equipped").isEmpty())title=BetaCopy.text("no_title",ko);
        title=BetaMedalUi.equippedTitle(this,title);paint.setTextSize(48);StaticLayout nameLayout=StaticLayout.Builder.obtain(name,0,name.length(),paint,700).setLineSpacing(0,1.35f).setIncludePad(true).build();paint.setTextSize(34);StaticLayout titleLayout=StaticLayout.Builder.obtain(title,0,title.length(),paint,700).setLineSpacing(0,1.4f).setIncludePad(true).build();int height=820+nameLayout.getHeight()+titleLayout.getHeight();Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(0xff11151c);Paint fill=new Paint(3);fill.setColor(0xff1b2431);canvas.drawRoundRect(32,32,width-32,height-32,28,28,fill);
        String frame=BetaPreferences.prefs(this).getString(account+":frame","");if(!frame.isEmpty()&&s.optJSONObject("honors").has(frame)){Paint border=new Paint(3);border.setStyle(Paint.Style.STROKE);border.setStrokeWidth(frame.equals("rpg3.frame_50")?8:4);border.setColor(Ui.accent(this,true));canvas.drawRoundRect(42,42,width-42,height-42,24,24,border);}
        int y=78;paint.setTextSize(48);canvas.save();canvas.translate(70,y);nameLayout.draw(canvas);canvas.restore();y+=nameLayout.getHeight()+12;paint.setTextSize(34);canvas.save();canvas.translate(70,y);titleLayout.draw(canvas);canvas.restore();y+=titleLayout.getHeight()+65;
        paint.setColor(Ui.accent(this,true));paint.setTextSize(66);canvas.drawText("Lv. "+s.optInt("level"),70,y,paint);y+=45;paint.setTextSize(28);paint.setColor(0xffc2cedd);canvas.drawText(BetaCopy.text("xp",ko)+" "+s.optLong("progress")+" / "+s.optLong("next_cost"),70,y,paint);y+=25;fill.setColor(0xff647182);canvas.drawRoundRect(70,y,770,y+12,6,6,fill);fill.setColor(Ui.accent(this,true));canvas.drawRoundRect(70,y,70+700*Math.min(1,s.optLong("progress")/(float)Math.max(1,s.optLong("next_cost"))),y+12,6,6,fill);y+=70;
        paint.setTextSize(26);canvas.drawText(BetaCopy.text("counts",ko,s.optJSONObject("honors").length(),s.optJSONObject("titles").length()),70,y,paint);y+=30;for(int i=0;i<medals.size();i++){BetaEmblem emblem=new BetaEmblem(medals.get(i),true,true);emblem.setBounds(70+i*230,y,210+i*230,y+140);emblem.draw(canvas);}y+=200;
        paint.setTextSize(25);canvas.drawText("GPT HUD",70,y,paint);if(TrialDemo.active(this)){paint.setTextSize(23);canvas.drawText(ko?"가상 데모 · 실제 기록 아님":"Synthetic demo, not real records",70,y+42,paint);}return bitmap;
    }
    void write(Uri uri){byte[] bytes=pending;pending=null;String key=pendingAccount;pendingAccount=null;if(uri==null||bytes==null||!BetaUi.current(this,key))return;BetaGrowthStore.WORKER.execute(()->{boolean ok=false;try{if(!BetaGrowthStore.current(this,key))return;try(java.io.OutputStream out=getContentResolver().openOutputStream(uri,"w")){if(out==null)throw new java.io.IOException();out.write(bytes);ok=true;}}catch(Exception ignored){}final boolean saved=ok;runOnUiThread(()->{if(BetaUi.current(this,key))Toast.makeText(this,BetaCopy.t(this,saved?"saved":"failed"),Toast.LENGTH_LONG).show();});});}
    void share(){String key=account;if(png==null||!BetaUi.current(this,key))return;byte[] bytes=png.clone();BetaGrowthStore.WORKER.execute(()->{Uri uri=null;try{if(!BetaGrowthStore.current(this,key))return;java.io.File folder=new java.io.File(getCacheDir(),"profile-share");folder.mkdirs();java.io.File file=new java.io.File(folder,java.util.UUID.randomUUID()+".png");try(java.io.FileOutputStream out=new java.io.FileOutputStream(file)){out.write(bytes);}uri=FileProvider.getUriForFile(this,getPackageName()+".profile.files",file);}catch(Exception ignored){}final Uri value=uri;runOnUiThread(()->{if(value==null||!BetaUi.current(this,key))return;Intent intent=new Intent(Intent.ACTION_SEND).setType("image/png").putExtra(Intent.EXTRA_STREAM,value).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("GPT HUD",value));startActivity(Intent.createChooser(intent,BetaCopy.t(this,"share")));});});}
}
